#!/usr/bin/env python3
"""Amazon Product Catalog Performance Report Generator"""

import pandas as pd
import numpy as np
from pathlib import Path
import json
import re

# Load and clean data
def load_data(csv_path):
    df = pd.read_csv(csv_path)

    # Clean price columns
    df['discounted_price'] = df['discounted_price'].astype(str).str.replace('₹', '').str.replace(',', '').astype(float)
    df['actual_price'] = df['actual_price'].astype(str).str.replace('₹', '').str.replace(',', '').astype(float)

    # Clean discount percentage
    df['discount_percentage'] = df['discount_percentage'].astype(str).str.replace('%', '').astype(float)

    # Clean rating count
    df['rating_count'] = df['rating_count'].astype(str).str.replace(',', '')
    df['rating_count'] = pd.to_numeric(df['rating_count'], errors='coerce')

    # Clean rating
    df['rating'] = pd.to_numeric(df['rating'], errors='coerce')

    # Extract top-level category
    df['top_category'] = df['category'].astype(str).str.split('|').str[0].str.replace('&', ' & ')

    return df

def calculate_kpis(df):
    kpis = {
        'total_products': len(df),
        'avg_rating': df['rating'].mean(),
        'avg_discount': df['discount_percentage'].mean(),
        'median_rating_count': df['rating_count'].median(),
        'high_rating_share': (df['rating'] >= 4.0).sum() / len(df) * 100,
    }
    return kpis

def category_analysis(df):
    cat_stats = df.groupby('top_category').agg({
        'rating': ['mean', 'count'],
        'discount_percentage': 'mean',
        'rating_count': 'median'
    }).round(2)
    cat_stats.columns = ['avg_rating', 'product_count', 'avg_discount', 'median_rating_count']
    cat_stats = cat_stats.sort_values('avg_rating', ascending=False)
    return cat_stats

def price_discount_analysis(df):
    # Correlation between discount and rating
    corr_discount_rating = df['discount_percentage'].corr(df['rating'])
    corr_discount_count = df['discount_percentage'].corr(df['rating_count'])

    return {
        'discount_rating_corr': corr_discount_rating,
        'discount_count_corr': corr_discount_count
    }

def rating_distribution(df):
    bins = [0, 3.0, 3.5, 4.0, 4.5, 5.0]
    labels = ['1-3', '3-3.5', '3.5-4', '4-4.5', '4.5-5']
    df['rating_bucket'] = pd.cut(df['rating'], bins=bins, labels=labels, include_lowest=True)
    dist = df['rating_bucket'].value_counts().sort_index()
    return dist

def top_products(df, n=10):
    return df.nlargest(n, 'rating_count')[['product_name', 'rating', 'rating_count', 'discount_percentage', 'top_category']]

def generate_chart_data(df):
    # Category performance chart
    cat_stats = category_analysis(df)

    # Rating distribution data
    rating_dist = rating_distribution(df)

    # Discount vs Rating scatter buckets
    df['discount_bucket'] = pd.cut(df['discount_percentage'], bins=[0, 20, 40, 60, 80, 100],
                                    labels=['0-20%', '20-40%', '40-60%', '60-80%', '80-100%'])
    discount_rating = df.groupby('discount_bucket', observed=True)['rating'].mean()

    return {
        'category_chart': cat_stats.to_dict(),
        'rating_dist': rating_dist.to_dict(),
        'discount_rating': discount_rating.to_dict()
    }

def generate_html_report(df, output_path):
    kpis = calculate_kpis(df)
    cat_stats = category_analysis(df)
    analysis = price_discount_analysis(df)
    rating_dist = rating_distribution(df)
    top_prods = top_products(df)
    chart_data = generate_chart_data(df)

    # Category JSON for chart
    cat_json = []
    for cat, row in cat_stats.iterrows():
        cat_json.append({
            'category': cat,
            'avg_rating': float(row['avg_rating']),
            'product_count': int(row['product_count']),
            'avg_discount': float(row['avg_discount'])
        })

    html = f"""<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Amazon Product Catalog Performance & Customer Sentiment Analysis</title>
    <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
    <style>
        :root {{
            --primary: #232F3E;
            --secondary: #37475A;
            --accent: #FF9900;
            --success: #008060;
            --warning: #D97706;
            --bg: #F5F7FA;
            --card-bg: #FFFFFF;
            --text: #1A1A1A;
            --text-muted: #6B7280;
        }}
        * {{ margin: 0; padding: 0; box-sizing: border-box; }}
        body {{
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
            background: var(--bg);
            color: var(--text);
            line-height: 1.6;
        }}
        .container {{ max-width: 1400px; margin: 0 auto; padding: 40px 20px; }}
        header {{
            background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
            color: white;
            padding: 60px 40px;
            border-radius: 16px;
            margin-bottom: 40px;
        }}
        header h1 {{ font-size: 2.5rem; font-weight: 700; margin-bottom: 10px; }}
        header p {{ font-size: 1.1rem; opacity: 0.9; }}
        .kpi-grid {{
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
            gap: 20px;
            margin-bottom: 40px;
        }}
        .kpi-card {{
            background: var(--card-bg);
            padding: 24px;
            border-radius: 12px;
            box-shadow: 0 2px 8px rgba(0,0,0,0.08);
            text-align: center;
        }}
        .kpi-card .label {{ font-size: 0.85rem; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.5px; }}
        .kpi-card .value {{ font-size: 2.2rem; font-weight: 700; color: var(--primary); margin: 8px 0; }}
        .kpi-card .sub {{ font-size: 0.85rem; color: var(--text-muted); }}
        .section {{
            background: var(--card-bg);
            border-radius: 12px;
            padding: 32px;
            margin-bottom: 32px;
            box-shadow: 0 2px 8px rgba(0,0,0,0.08);
        }}
        .section h2 {{ font-size: 1.5rem; color: var(--primary); margin-bottom: 24px; padding-bottom: 12px; border-bottom: 2px solid var(--accent); }}
        .section h3 {{ font-size: 1.1rem; color: var(--secondary); margin: 20px 0 12px; }}
        .chart-grid {{
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
            gap: 24px;
        }}
        .chart-container {{ position: relative; height: 300px; }}
        table {{ width: 100%; border-collapse: collapse; margin-top: 20px; }}
        th, td {{ padding: 12px; text-align: left; border-bottom: 1px solid #E5E7EB; }}
        th {{ background: var(--bg); font-weight: 600; color: var(--secondary); }}
        tr:hover {{ background: #F9FAFB; }}
        .highlight-box {{
            background: linear-gradient(135deg, #FEF3C7 0%, #FDE68A 100%);
            padding: 20px;
            border-radius: 8px;
            border-left: 4px solid var(--accent);
            margin: 16px 0;
        }}
        .insight {{ padding: 16px; background: #F0FDF4; border-radius: 8px; border-left: 4px solid var(--success); margin: 12px 0; }}
        .warning {{ padding: 16px; background: #FEF2F2; border-radius: 8px; border-left: 4px solid #EF4444; margin: 12px 0; }}
        .recommendations {{ display: grid; gap: 16px; }}
        .rec-card {{ display: flex; gap: 16px; padding: 20px; background: var(--bg); border-radius: 8px; }}
        .rec-number {{ background: var(--accent); color: white; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 700; flex-shrink: 0; }}
        .rec-content h4 {{ margin-bottom: 4px; }}
        .rec-content p {{ color: var(--text-muted); font-size: 0.9rem; }}
        .metrics-row {{ display: flex; gap: 40px; flex-wrap: wrap; margin: 20px 0; }}
        .metric-box {{ flex: 1; min-width: 200px; }}
        .metric-box label {{ font-size: 0.8rem; color: var(--text-muted); text-transform: uppercase; }}
        .metric-box .num {{ font-size: 1.8rem; font-weight: 700; }}
        .metric-box .num.positive {{ color: var(--success); }}
        .metric-box .num.negative {{ color: #EF4444; }}
        .footer {{ text-align: center; padding: 40px; color: var(--text-muted); font-size: 0.85rem; }}
    </style>
