#!/usr/bin/env python3
"""Amazon Product Catalog Performance Report Generator"""

import pandas as pd
import numpy as np
from pathlib import Path
import json
import re

# Load and clean data
def load_data(csv_path):
    df = pd.read_csv(csv_path)

    # Clean price columns
    df['discounted_price'] = df['discounted_price'].astype(str).str.replace('₹', '').str.replace(',', '').astype(float)
    df['actual_price'] = df['actual_price'].astype(str).str.replace('₹', '').str.replace(',', '').astype(float)

    # Clean discount percentage
    df['discount_percentage'] = df['discount_percentage'].astype(str).str.replace('%', '').astype(float)

    # Clean rating count
    df['rating_count'] = df['rating_count'].astype(str).str.replace(',', '')
    df['rating_count'] = pd.to_numeric(df['rating_count'], errors='coerce')

    # Clean rating
    df['rating'] = pd.to_numeric(df['rating'], errors='coerce')

    # Extract top-level category
    df['top_category'] = df['category'].astype(str).str.split('|').str[0].str.replace('&', ' & ')

    return df

def calculate_kpis(df):
    kpis = {
        'total_products': len(df),
        'avg_rating': df['rating'].mean(),
        'avg_discount': df['discount_percentage'].mean(),
        'median_rating_count': df['rating_count'].median(),
        'high_rating_share': (df['rating'] >= 4.0).sum() / len(df) * 100,
    }
    return kpis

def category_analysis(df):
    cat_stats = df.groupby('top_category').agg({
        'rating': ['mean', 'count'],
        'discount_percentage': 'mean',
        'rating_count': 'median'
    }).round(2)
    cat_stats.columns = ['avg_rating', 'product_count', 'avg_discount', 'median_rating_count']
    cat_stats = cat_stats.sort_values('avg_rating', ascending=False)
    return cat_stats

def price_discount_analysis(df):
    # Correlation between discount and rating
    corr_discount_rating = df['discount_percentage'].corr(df['rating'])
    corr_discount_count = df['discount_percentage'].corr(df['rating_count'])

    return {
        'discount_rating_corr': corr_discount_rating,
        'discount_count_corr': corr_discount_count
    }

def rating_distribution(df):
    bins = [0, 3.0, 3.5, 4.0, 4.5, 5.0]
    labels = ['1-3', '3-3.5', '3.5-4', '4-4.5', '4.5-5']
    df['rating_bucket'] = pd.cut(df['rating'], bins=bins, labels=labels, include_lowest=True)
    dist = df['rating_bucket'].value_counts().sort_index()
    return dist

def top_products(df, n=10):
    return df.nlargest(n, 'rating_count')[['product_name', 'rating', 'rating_count', 'discount_percentage', 'top_category']]

def generate_chart_data(df):
    # Category performance chart
    cat_stats = category_analysis(df)

    # Rating distribution data
    rating_dist = rating_distribution(df)

    # Discount vs Rating scatter buckets
    df['discount_bucket'] = pd.cut(df['discount_percentage'], bins=[0, 20, 40, 60, 80, 100],
                                    labels=['0-20%', '20-40%', '40-60%', '60-80%', '80-100%'])
    discount_rating = df.groupby('discount_bucket', observed=True)['rating'].mean()

    return {
        'category_chart': cat_stats.to_dict(),
        'rating_dist': rating_dist.to_dict(),
        'discount_rating': discount_rating.to_dict()
    }

